function(...args) { const cp = s => Array.from(s);
const trim = s => s.replace(/^[\u0009-\u000D\u0020\u0085\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]+|[\u0009-\u000D\u0020\u0085\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]+$/gu, '');
const split = (s, sep) => sep === '' ? cp(s) : s.split(sep);
const replace = (s, a, b) => a === '' ? s : s.split(a).join(b);
const parse = (s, fallback) => { let t = s.replace(/\s/g, ''); if (!t.includes('.')) t = t.replace(',', '.'); return /^[+-]?(\d+\.?\d*|\.\d+)$/.test(t) ? parseFloat(t) : fallback; };
const step = seed => { let x = seed | 0; if (x === 0) x = 0x2545F491; x ^= x << 13; x ^= x >>> 17; x ^= x << 5; return x | 0; };
return ((text, search, opening, closing) => text.split(search).join(opening + search + closing))(...args); }
